theorem Batch3N9.Problem97.signedArea2_reflection_neg {q v2 y u : ℝ²}
    (hmid : signedArea2 (midpoint ℝ y u) q v2 = 0) :
    signedArea2 u q v2 = - signedArea2 y q v2 := by sorry

lemma Problem97.signedArea2_eq_zero_exists_smul {v1 v2 v3 : ℝ²}
    (h21 : v2 ≠ v1) (h : signedArea2 v1 v2 v3 = 0) :
    ∃ r : ℝ, v3 - v1 = r • (v2 - v1) := by sorry
